mapper.select:
select *
from rabbit_abnormal_conditions
where house_id = #{houseId}

    and is_deal = #{isDeal}

order by warning_time desc, id desc

select *
from rabbit_abnormal_conditions
where house_id = #{houseId} and id = #{id}

mapper.update:
update rabbit_abnormal_conditions
set is_deal = #{deal},
    update_by = #{updateBy},
    update_time = now()
where id = #{id} and house_id = #{houseId}
  and is_deal <> #{deal}

mapper.select:
select count(1)
from rabbit_abnormal_conditions a
         join rabbits r on r.id = a.rabbit_id and r.house_id = a.house_id
where a.house_id = #{houseId}
  and a.cage_id = #{cageId}
  and a.is_deal = false
